-- Reproducible seed for the 40 technical-knowledge questions per vehicle.
-- Questions cover common land-vehicle systems and marine onboard systems.
-- Optional equipment and exact maintenance intervals must be checked against each
-- individual vehicle's VIN-specific operator manual and actual outfitting.
with land_questions as (
 select * from jsonb_to_recordset($land$[{"prompt":"A cosa serve il filtro dell’aria motore?","options":["A lubrificare i cilindri","A ridurre la pressione dei freni","A trattenere particelle e impurità prima che l’aria entri nel motore","A raffreddare il liquido refrigerante"],"correct_index":2,"explanation":"Filtrazione dell’aria di aspirazione. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.iveco.com/italy/scopri-iveco/Contact-Us/Post-vendita-Acquirente","source_note":"Filtrazione dell’aria di aspirazione"},{"prompt":"A cosa serve il liquido refrigerante nel circuito motore?","options":["A regolare la pressione degli pneumatici","A lubrificare il cambio","A pulire il filtro aria","A trasferire calore e proteggere il circuito da corrosione e gelo secondo specifica"],"correct_index":3,"explanation":"Circuito di raffreddamento e specifica del refrigerante. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.iveco.com/italy/scopri-iveco/Contact-Us/Post-vendita-Acquirente","source_note":"Circuito di raffreddamento e specifica del refrigerante"},{"prompt":"A cosa serve la batteria di avviamento?","options":["Controllare la pressione del carburante","Fornire energia elettrica per l’avviamento e per i sistemi a veicolo fermo","Assorbire il calore dei freni","Trasmettere coppia al differenziale"],"correct_index":1,"explanation":"Batteria e alimentazione elettrica. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA","source_note":"Batteria e alimentazione elettrica"},{"prompt":"A cosa serve la pompa dell’acqua del motore?","options":["Azionare il differenziale","Far circolare il refrigerante nel circuito","Comprimere l’aria nei pneumatici","Regolare la convergenza"],"correct_index":1,"explanation":"Pompa e circolazione del liquido refrigerante. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.iveco.com/italy/-/media/Iveco---Press-Import/Pdfs/Nuovo-DAILY-SALONE-CAMPER-2011.pdf?rev=f0077a871a954617b3408c4500c2e2ad","source_note":"Pompa e circolazione del liquido refrigerante"},{"prompt":"A cosa serve la ripartizione elettronica della forza frenante (EBD)?","options":["A regolare il servosterzo","Adattare la distribuzione della forza frenante tra gli assi in funzione delle condizioni rilevate","A controllare il regime del motore","A sostituire il liquido freni"],"correct_index":1,"explanation":"Ripartizione elettronica della frenata. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA","source_note":"Ripartizione elettronica della frenata"},{"prompt":"A cosa serve un fusibile nell’impianto elettrico?","options":["A regolare la pressione dell’olio","A mantenere costante la temperatura del motore","A interrompere il circuito in caso di corrente eccessiva, proteggendo il cablaggio","A ricaricare la batteria"],"correct_index":2,"explanation":"Protezione dei circuiti elettrici. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA","source_note":"Protezione dei circuiti elettrici"},{"prompt":"A cosa serve una barra antirollio?","options":["A comandare il differenziale","A regolare il gioco valvole","A collegare elasticamente i lati della sospensione e limitare il rollio della carrozzeria","A misurare il livello del refrigerante"],"correct_index":2,"explanation":"Barra stabilizzatrice e rollio. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.monroe.com/technical-resources/ride-and-handling.html","source_note":"Barra stabilizzatrice e rollio"},{"prompt":"A cosa serve una scatola di rinvio (transfer case) nei veicoli 4x4 che ne sono dotati?","options":["A misurare la profondità del battistrada","A gestire i tergicristalli","A raffreddare i freni","A distribuire la coppia tra gli assi e, secondo il sistema, selezionare rapporti o modalità di trazione"],"correct_index":3,"explanation":"Scatola di rinvio e modalità 4WD. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.jeep.com/content/dam/cross-regional/stellantis/jeep/latam-rol/chile/es_cl/2024/Manuales/Jeep%20Wrangler.pdf","source_note":"Scatola di rinvio e modalità 4WD"},{"prompt":"Che cosa caratterizza un sistema di iniezione Common Rail?","options":["Una candela per ogni ruota","Una pompa che lubrifica il cambio","Un accumulatore comune di carburante ad alta pressione alimenta gli iniettori","Un carburatore con galleggiante"],"correct_index":2,"explanation":"Iniezione diesel Common Rail. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.iveco.com/italy/-/media/Iveco---Press-Import/Pdfs/Nuovo-DAILY-SALONE-CAMPER-2011.pdf?rev=f0077a871a954617b3408c4500c2e2ad","source_note":"Iniezione diesel Common Rail"},{"prompt":"Che cosa distingue una trasmissione a variazione continua (CVT)?","options":["Varia il rapporto di trasmissione in modo continuo entro il proprio campo di funzionamento","Usa sempre una sola marcia fissa","Funziona senza lubrificante","Non trasmette coppia alle ruote"],"correct_index":0,"explanation":"Trasmissione Lineartronic CVT e variazione del rapporto. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA","source_note":"Trasmissione Lineartronic CVT e variazione del rapporto"},{"prompt":"Che cosa monitora il TPMS?","options":["La tensione della cinghia servizi","La temperatura del cambio","La pressione degli pneumatici e, secondo il sistema, eventuali anomalie dei sensori","La quantità di olio motore"],"correct_index":2,"explanation":"Sistema di monitoraggio pressione pneumatici. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA","source_note":"Sistema di monitoraggio pressione pneumatici"},{"prompt":"Che cosa può indicare un’usura irregolare degli pneumatici?","options":["Che il serbatoio è vuoto","Un problema di pressione, assetto, equilibratura o componenti della sospensione da verificare","Che l’ABS è sempre attivo","Che il motore ha più potenza"],"correct_index":1,"explanation":"Usura pneumatici e controlli di assetto. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.nhtsa.gov/vehicle-safety/tires","source_note":"Usura pneumatici e controlli di assetto"},{"prompt":"Che cosa rappresenta l’indice di carico di uno pneumatico?","options":["Il diametro del cerchio in millimetri","La capacità di carico massima associata allo pneumatico nelle condizioni previste","La pressione del liquido freni","La velocità massima del motore"],"correct_index":1,"explanation":"Indice di carico e specifiche dello pneumatico. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.nhtsa.gov/vehicle-safety/tires","source_note":"Indice di carico e specifiche dello pneumatico"},{"prompt":"Che cosa segnala normalmente una spia rossa di pressione olio durante la marcia?","options":["Che l’ABS è attivo","Che il serbatoio carburante è pieno","Che il filtro abitacolo è pulito","Una possibile insufficiente pressione di lubrificazione: occorre fermarsi in sicurezza e verificare"],"correct_index":3,"explanation":"Spia pressione olio e arresto cautelativo. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA","source_note":"Spia pressione olio e arresto cautelativo"},{"prompt":"Come agisce il freno a disco?","options":["Un magnete rallenta il veicolo senza contatto","Una cinghia blocca l’albero motore","Le pastiglie stringono il disco solidale alla ruota, generando attrito frenante","Una pompa comprime il carburante"],"correct_index":2,"explanation":"Pinza, pastiglie e disco freno. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.nhtsa.gov/vehicle-safety/brakes","source_note":"Pinza, pastiglie e disco freno"},{"prompt":"Come deve essere considerato l’airbag rispetto alla cintura di sicurezza?","options":["Deve essere disattivato in ogni viaggio","È un sistema supplementare e non sostituisce la cintura","È utile solo a veicolo fermo","Sostituisce sempre la cintura"],"correct_index":1,"explanation":"Airbag come sistema supplementare di ritenuta. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.nhtsa.gov/vehicle-safety/air-bags","source_note":"Airbag come sistema supplementare di ritenuta"},{"prompt":"Come viene azionato un turbocompressore tradizionale?","options":["Dalla rotazione delle ruote posteriori","Dall’energia dei gas di scarico che mette in rotazione la turbina collegata al compressore","Dalla pompa ABS","Dal motorino dei tergicristalli"],"correct_index":1,"explanation":"Turbocompressore a gas di scarico. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.iveco.com/italy/-/media/Iveco---Press-Import/Pdfs/Nuovo-DAILY-SALONE-CAMPER-2011.pdf?rev=f0077a871a954617b3408c4500c2e2ad","source_note":"Turbocompressore a gas di scarico"},{"prompt":"Cosa indica una temperatura del liquido refrigerante nella zona di surriscaldamento?","options":["Che il sistema di scarico è freddo","Che la batteria è completamente carica","Una condizione anomala: fermarsi in sicurezza e seguire la procedura del costruttore","Che il motore può essere accelerato al massimo"],"correct_index":2,"explanation":"Spia temperatura refrigerante e gestione del surriscaldamento. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA","source_note":"Spia temperatura refrigerante e gestione del surriscaldamento"},{"prompt":"Perché il battistrada deve avere profondità adeguata?","options":["Per mantenere capacità di aderenza e drenaggio dell’acqua secondo i limiti prescritti","Per aumentare la cilindrata","Per impedire la rotazione delle ruote","Per ridurre il carico sugli ammortizzatori"],"correct_index":0,"explanation":"Battistrada e sicurezza dello pneumatico. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.nhtsa.gov/vehicle-safety/tires","source_note":"Battistrada e sicurezza dello pneumatico"},{"prompt":"Qual è il compito degli ammortizzatori?","options":["Sostituire le molle","Aumentare il rapporto di compressione","Regolare la pressione dell’olio","Smorzare le oscillazioni della sospensione"],"correct_index":3,"explanation":"Smorzamento delle oscillazioni. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.monroe.com/technical-resources/ride-and-handling.html","source_note":"Smorzamento delle oscillazioni"},{"prompt":"Qual è il compito dei sensori ruota dell’ABS?","options":["Rilevare la velocità di rotazione delle ruote per individuare il rischio di bloccaggio","Misurare la temperatura dell’olio","Misurare la pressione del liquido refrigerante","Controllare il livello del carburante"],"correct_index":0,"explanation":"Sensori di velocità ruota e controllo ABS. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.nhtsa.gov/equipment/anti-lock-braking-systems-abs","source_note":"Sensori di velocità ruota e controllo ABS"},{"prompt":"Qual è il compito del filtro carburante?","options":["Trattenere impurità e, nei sistemi previsti, separare l’acqua dal carburante","Aumentare il numero di ottani","Raffreddare il serbatoio","Misurare il livello dell’olio"],"correct_index":0,"explanation":"Filtrazione carburante e separazione dell’acqua. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.iveco.com/italy/scopri-iveco/Contact-Us/Post-vendita-Acquirente","source_note":"Filtrazione carburante e separazione dell’acqua"},{"prompt":"Qual è il compito del termostato del circuito di raffreddamento?","options":["Filtrare il carburante","Misurare la pressione degli pneumatici","Regolare il passaggio del refrigerante in funzione della temperatura","Azionare il motorino di avviamento"],"correct_index":2,"explanation":"Termostato e controllo della temperatura del motore. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.volvopenta.com/-/media/volvopenta/local/uk/apprenticeship/level-2-foundation-level-marine-engineering.pdf","source_note":"Termostato e controllo della temperatura del motore"},{"prompt":"Qual è il compito della cremagliera dello sterzo?","options":["Trasformare la rotazione del volante in spostamento laterale delle ruote sterzanti","Convertire la pressione del carburante in coppia","Regolare la convergenza in automatico","Azionare il sistema di raffreddamento"],"correct_index":0,"explanation":"Sterzo a cremagliera. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA","source_note":"Sterzo a cremagliera"},{"prompt":"Qual è il compito principale dell’alternatore?","options":["Alimentare l’impianto elettrico e ricaricare la batteria durante il funzionamento","Avviare meccanicamente il motore a freddo","Modificare il rapporto del cambio","Raffreddare l’olio motore"],"correct_index":0,"explanation":"Alternatore e circuito di ricarica. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.iveco.com/italy/scopri-iveco/Contact-Us/Post-vendita-Acquirente","source_note":"Alternatore e circuito di ricarica"},{"prompt":"Qual è la funzione del catalizzatore?","options":["Favorire la trasformazione chimica di inquinanti presenti nei gas di scarico","Aumentare la coppia alle ruote","Filtrare l’olio motore","Raffreddare il carburante"],"correct_index":0,"explanation":"Trattamento catalitico dei gas di scarico. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.iveco.com/italy/-/media/Iveco---Press-Import/Pdfs/Nuovo-DAILY-SALONE-CAMPER-2011.pdf?rev=f0077a871a954617b3408c4500c2e2ad","source_note":"Trattamento catalitico dei gas di scarico"},{"prompt":"Qual è la funzione del differenziale su un asse motore?","options":["Aumentare la pressione dell’olio","Consentire alle ruote dello stesso asse di ruotare a velocità diverse in curva","Frenare automaticamente il veicolo","Bloccare sempre le due ruote alla stessa velocità"],"correct_index":1,"explanation":"Differenziale e cinematica in curva. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.jeep.com/content/dam/cross-regional/stellantis/jeep/latam-rol/chile/es_cl/2024/Manuales/Jeep%20Wrangler.pdf","source_note":"Differenziale e cinematica in curva"},{"prompt":"Qual è la funzione del filtro antiparticolato diesel (DPF/FAP)?","options":["Filtrare l’aria dell’abitacolo","Raffreddare il liquido freni","Aumentare la pressione degli pneumatici","Trattenere il particolato dei gas di scarico e consentirne la rigenerazione secondo il sistema"],"correct_index":3,"explanation":"Filtro antiparticolato e trattamento dei gas di scarico. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.iveco.com/italy/-/media/Iveco---Press-Import/Pdfs/Nuovo-DAILY-SALONE-CAMPER-2011.pdf?rev=f0077a871a954617b3408c4500c2e2ad","source_note":"Filtro antiparticolato e trattamento dei gas di scarico"},{"prompt":"Qual è la funzione del freno di stazionamento?","options":["Mantenere fermo il veicolo quando è parcheggiato","Aumentare la pressione di sovralimentazione","Sostituire l’ABS durante la marcia","Raffreddare le pastiglie"],"correct_index":0,"explanation":"Freno di stazionamento e immobilizzazione. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA","source_note":"Freno di stazionamento e immobilizzazione"},{"prompt":"Qual è la funzione del liquido freni in un impianto idraulico?","options":["Alimentare il servosterzo elettrico","Raffreddare il radiatore","Lubrificare la catena di distribuzione","Trasmettere la pressione esercitata sul comando ai dispositivi frenanti"],"correct_index":3,"explanation":"Liquido freni e trasmissione idraulica della pressione. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.nhtsa.gov/vehicle-safety/brakes","source_note":"Liquido freni e trasmissione idraulica della pressione"},{"prompt":"Qual è la funzione del motorino di avviamento?","options":["Azionare il servofreno in marcia","Raffreddare il motore","Regolare il rapporto del cambio","Far ruotare il motore termico fino all’avviamento autonomo"],"correct_index":3,"explanation":"Motorino e circuito di avviamento. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.iveco.com/italy/scopri-iveco/Contact-Us/Post-vendita-Acquirente","source_note":"Motorino e circuito di avviamento"},{"prompt":"Qual è la funzione del pretensionatore della cintura, se presente?","options":["Bloccare il motore in marcia ordinaria","Allentare la cintura in caso di urto","Sostituire il poggiatesta","Ridurre rapidamente il gioco della cintura all’inizio dell’urto"],"correct_index":3,"explanation":"Pretensionatore e ritenuta dell’occupante. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.nhtsa.gov/vehicle-safety/seat-belts","source_note":"Pretensionatore e ritenuta dell’occupante"},{"prompt":"Qual è la funzione del tergicristallo e del lavavetro?","options":["Mantenere il campo visivo del conducente pulito in condizioni di pioggia o sporco","Raffreddare il parabrezza","Controllare la pressione degli pneumatici","Regolare la velocità del veicolo"],"correct_index":0,"explanation":"Visibilità e dispositivi tergicristallo. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA","source_note":"Visibilità e dispositivi tergicristallo"},{"prompt":"Qual è la funzione dell’intercooler nei motori sovralimentati che ne sono dotati?","options":["Ridurre la pressione degli pneumatici","Aumentare la temperatura dell’aria compressa","Filtrare l’olio del cambio","Raffreddare l’aria compressa prima dell’aspirazione, aumentando la densità della carica"],"correct_index":3,"explanation":"Intercooler e temperatura dell’aria di aspirazione. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.iveco.com/italy/-/media/Iveco---Press-Import/Pdfs/Nuovo-DAILY-SALONE-CAMPER-2011.pdf?rev=f0077a871a954617b3408c4500c2e2ad","source_note":"Intercooler e temperatura dell’aria di aspirazione"},{"prompt":"Qual è la funzione delle molle della sospensione?","options":["Raffreddare il differenziale","Sostenere il carico del veicolo e consentire il movimento elastico delle ruote rispetto alla scocca","Regolare l’iniezione","Frenare il disco"],"correct_index":1,"explanation":"Molle e sostegno della sospensione. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.monroe.com/technical-resources/ride-and-handling.html","source_note":"Molle e sostegno della sospensione"},{"prompt":"Qual è la funzione generale di un sistema di trazione integrale?","options":["Ridurre automaticamente lo spazio di frenata su ogni fondo","Aumentare la potenza nominale del motore","Trasmettere coppia a più assi secondo la logica del sistema","Sostituire il sistema frenante"],"correct_index":2,"explanation":"AWD e distribuzione della coppia. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.subaru.com/owners/vehicle-resources.html?model=2024-CTK-RRA","source_note":"AWD e distribuzione della coppia"},{"prompt":"Qual è la funzione primaria dell’olio motore?","options":["Comandare l’ABS","Lubrificare le parti in movimento e contribuire alla protezione dall’usura","Raffreddare direttamente i freni","Aumentare la pressione degli pneumatici"],"correct_index":1,"explanation":"Lubrificazione motore e manutenzione secondo manuale del costruttore. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.iveco.com/italy/scopri-iveco/Contact-Us/Post-vendita-Acquirente","source_note":"Lubrificazione motore e manutenzione secondo manuale del costruttore"},{"prompt":"Qual è lo scopo del sistema EGR nei motori che ne sono dotati?","options":["Aumentare la pressione dei pneumatici","Aumentare il livello del liquido refrigerante","Ricircolare una parte dei gas di scarico per ridurre la formazione di ossidi di azoto","Raffreddare il cambio"],"correct_index":2,"explanation":"Ricircolo dei gas di scarico e riduzione NOx. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.iveco.com/italy/-/media/Iveco---Press-Import/Pdfs/Nuovo-DAILY-SALONE-CAMPER-2011.pdf?rev=f0077a871a954617b3408c4500c2e2ad","source_note":"Ricircolo dei gas di scarico e riduzione NOx"},{"prompt":"Quale funzione svolge il radiatore?","options":["Dissipare verso l’aria il calore del refrigerante","Aumentare la pressione dell’olio","Trasmettere la coppia alle ruote","Alimentare gli iniettori"],"correct_index":0,"explanation":"Scambiatore di calore del circuito di raffreddamento. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.iveco.com/italy/-/media/Iveco---Press-Import/Pdfs/Nuovo-DAILY-SALONE-CAMPER-2011.pdf?rev=f0077a871a954617b3408c4500c2e2ad","source_note":"Scambiatore di calore del circuito di raffreddamento"},{"prompt":"Quando è preferibile controllare la pressione degli pneumatici per una misura attendibile?","options":["Solo quando si accende la spia","Subito dopo una lunga marcia ad alta velocità","Con il veicolo in curva","A pneumatici freddi, seguendo i valori prescritti dal costruttore"],"correct_index":3,"explanation":"Controllo della pressione a freddo. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.nhtsa.gov/vehicle-safety/tires","source_note":"Controllo della pressione a freddo"}]$land$::jsonb)
 as q(prompt text, options jsonb, correct_index smallint, explanation text, source_url text, source_note text)
),
sea_questions as (
 select * from jsonb_to_recordset($sea$[{"prompt":"A cosa serve il circuito di raffreddamento di un motore marino?","options":["A mantenere il motore entro il campo di temperatura previsto","A filtrare l’acqua potabile","A regolare la bussola","A comandare il verricello"],"correct_index":0,"explanation":"Raffreddamento e controllo della temperatura. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.boatus.org/study-guide/the-boat/","source_note":"Raffreddamento e controllo della temperatura"},{"prompt":"A cosa serve il radar di navigazione?","options":["Misurare la salinità","Sostituire la vedetta","Rilevare e rappresentare echi di bersagli e costa per supportare la navigazione e la valutazione del traffico","Regolare la portata delle pompe"],"correct_index":2,"explanation":"Radar e rilevamento dei bersagli. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.navcen.uscg.gov/","source_note":"Radar e rilevamento dei bersagli"},{"prompt":"A cosa serve il riduttore/invertitore di una linea d’asse?","options":["A trasmettere la potenza al propulsore e consentire, secondo il modello, marcia avanti, folle e indietro","A regolare i fanali","A misurare la pressione atmosferica","A raffreddare il carburante"],"correct_index":0,"explanation":"Trasmissione e invertitore marino. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.volvopenta.com/support/product-family/md22%20%28inb%29/","source_note":"Trasmissione e invertitore marino"},{"prompt":"A cosa serve il sistema di governo idraulico quando installato?","options":["A trasmettere il comando del timone mediante pressione del fluido","A regolare la carica delle batterie","A raffreddare il motore","A misurare la profondità"],"correct_index":0,"explanation":"Impianto di governo idraulico. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.boatus.org/study-guide/the-boat/","source_note":"Impianto di governo idraulico"},{"prompt":"A cosa serve il sistema DSC associato a una radio VHF compatibile?","options":["A controllare l’elica","A sostituire il GPS","A regolare la temperatura del motore","A inviare chiamate selettive digitali, comprese chiamate di soccorso secondo configurazione e registrazione"],"correct_index":3,"explanation":"Digital Selective Calling. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.navcen.uscg.gov/","source_note":"Digital Selective Calling"},{"prompt":"A cosa serve l’ecoscandaglio?","options":["Misurare la tensione della batteria","Individuare le perdite di carburante","Misurare il regime del motore","Stimare la profondità sotto la chiglia tramite impulsi acustici"],"correct_index":3,"explanation":"Misura della profondità mediante ecoscandaglio. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.navcen.uscg.gov/","source_note":"Misura della profondità mediante ecoscandaglio"},{"prompt":"A cosa serve la batteria di avviamento dell’unità?","options":["A comandare la bussola magnetica","A fornire energia al motorino di avviamento e ai sistemi elettrici previsti","A regolare la profondità","A raffreddare il motore"],"correct_index":1,"explanation":"Batterie e avviamento. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.volvopenta.com/-/media/volvopenta/local/uk/apprenticeship/level-2-foundation-level-marine-engineering.pdf","source_note":"Batterie e avviamento"},{"prompt":"A cosa serve un interruttore a galleggiante collegato alla pompa di sentina, se installato?","options":["A misurare il livello del carburante","Ad attivare automaticamente la pompa quando l’acqua raggiunge un livello prefissato","A comandare il radar","A regolare la bussola"],"correct_index":1,"explanation":"Attivazione automatica della pompa di sentina. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.boatus.org/study-guide/the-boat/","source_note":"Attivazione automatica della pompa di sentina"},{"prompt":"A cosa serve un salpancora elettrico, se installato?","options":["Regolare la pressione del motore","Comandare le luci di via","Agevolare la movimentazione della catena e dell’ancora","Raffreddare il verricello"],"correct_index":2,"explanation":"Salpancora e movimentazione dell’ancora. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.boatus.org/study-guide/the-boat/","source_note":"Salpancora e movimentazione dell’ancora"},{"prompt":"A cosa serve un separatore acqua/olio installato nel sistema di sentina?","options":["A rendere potabile l’acqua di mare","A limitare lo scarico in mare di idrocarburi presenti nell’acqua di sentina","Ad aumentare la potenza del motore","A regolare la velocità dell’elica"],"correct_index":1,"explanation":"Gestione degli idrocarburi e acqua di sentina. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.boatus.org/preserving-clean-water/boat-maintenance/","source_note":"Gestione degli idrocarburi e acqua di sentina"},{"prompt":"A cosa serve una paratia stagna?","options":["A regolare la bussola","A limitare la propagazione dell’allagamento tra compartimenti, se progettata e mantenuta integra","A sostenere il radar","A ridurre il consumo carburante"],"correct_index":1,"explanation":"Compartimentazione e contenimento dell’allagamento. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.boatus.org/study-guide/the-boat/","source_note":"Compartimentazione e contenimento dell’allagamento"},{"prompt":"A cosa serve uno scambiatore di calore in un motore marino con raffreddamento indiretto?","options":["A generare la spinta dell’elica","A trasferire calore tra circuito chiuso del motore e acqua di raffreddamento","A misurare la profondità","A separare il carburante dall’olio"],"correct_index":1,"explanation":"Scambiatore di calore e circuiti di raffreddamento. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.volvopenta.com/-/media/volvopenta/local/uk/apprenticeship/level-2-foundation-level-marine-engineering.pdf","source_note":"Scambiatore di calore e circuiti di raffreddamento"},{"prompt":"A cosa servono gli anodi sacrificali installati su parti metalliche immerse?","options":["A ridurre la resistenza dell’acqua","A misurare il pescaggio","A corrodersi preferenzialmente per proteggere altri metalli dalla corrosione galvanica","A lubrificare l’elica"],"correct_index":2,"explanation":"Anodi sacrificali e corrosione galvanica. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.boatus.org/study-guide/the-boat/","source_note":"Anodi sacrificali e corrosione galvanica"},{"prompt":"Che cosa può indicare la presenza di acqua o emulsione anomala nell’olio motore?","options":["Che la batteria è scarica","Che il timone è in posizione centrale","Che il serbatoio carburante è pieno","Una possibile contaminazione o anomalia da verificare prima di proseguire l’esercizio"],"correct_index":3,"explanation":"Controllo contaminazione e stato dell’olio. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.volvopenta.com/-/media/volvopenta/local/uk/apprenticeship/level-2-foundation-level-marine-engineering.pdf","source_note":"Controllo contaminazione e stato dell’olio"},{"prompt":"Perché è utile risciacquare con acqua dolce il circuito di raffreddamento di un fuoribordo dopo l’uso in acqua salata, secondo le istruzioni del costruttore?","options":["Per limitare depositi e accumuli di sale nei passaggi d’acqua","Per svuotare il serbatoio carburante","Per aumentare la salinità interna","Per aumentare la potenza nominale"],"correct_index":0,"explanation":"Risciacquo dei passaggi di raffreddamento. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://servicelit.mercurymarine.com/mnetdata/SERVICE/MERMAR/OWNER/15/8M0105247.PDF","source_note":"Risciacquo dei passaggi di raffreddamento"},{"prompt":"Perché il flusso d’acqua di raffreddamento visibile su un fuoribordo va controllato?","options":["Per misurare il regime motore","Può fornire un’indicazione del corretto funzionamento della pompa e del circuito di raffreddamento","Per verificare il livello del carburante","Per verificare il funzionamento del GPS"],"correct_index":1,"explanation":"Controllo del flusso pilota dell’acqua. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.yamaha-motor.eu/content/dam/yamaha-motor-europe/marine/dealers/2022-workshop-dealer-guide.pdf","source_note":"Controllo del flusso pilota dell’acqua"},{"prompt":"Perché le cime di ormeggio devono essere dimensionate e controllate?","options":["Per resistere ai carichi di ormeggio e ridurre il rischio di rottura","Per regolare il dislocamento","Per aumentare la velocità in navigazione","Per misurare il fondale"],"correct_index":0,"explanation":"Cime di ormeggio e carichi. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.boatus.org/study-guide/the-boat/","source_note":"Cime di ormeggio e carichi"},{"prompt":"Perché le giubbotti salvagente devono essere mantenuti accessibili e in efficienza?","options":["Per sostituire la zattera di salvataggio in ogni scenario","Per segnalare la rotta al radar","Per consentire il galleggiamento e aumentare le possibilità di sopravvivenza in acqua","Per proteggere dal rumore dei motori"],"correct_index":2,"explanation":"Dotazioni individuali di galleggiamento. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.uscgboating.org/","source_note":"Dotazioni individuali di galleggiamento"},{"prompt":"Perché le prese a mare e le relative valvole devono essere controllate?","options":["Per assicurare tenuta e possibilità di isolare una presa d’acqua in caso di guasto","Per aumentare la potenza del motore","Per regolare la velocità massima","Per misurare la profondità"],"correct_index":0,"explanation":"Prese a mare e valvole di intercettazione. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.boatus.org/study-guide/the-boat/","source_note":"Prese a mare e valvole di intercettazione"},{"prompt":"Perché le tubazioni e i raccordi del carburante devono essere controllati periodicamente?","options":["Per individuare perdite, corrosione o deterioramento che possono creare rischio d’incendio e avaria","Per aumentare la spinta idrostatica","Per aumentare la velocità massima","Per regolare il pescaggio"],"correct_index":0,"explanation":"Controllo tubazioni e raccordi carburante. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.boatus.org/preserving-clean-water/boat-maintenance/","source_note":"Controllo tubazioni e raccordi carburante"},{"prompt":"Qual è il compito del timone?","options":["Raffreddare i motori","Filtrare il carburante","Generare una forza idrodinamica che contribuisce a modificare la direzione dell’unità","Misurare la velocità sull’acqua"],"correct_index":2,"explanation":"Timone e governo dell’unità. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://weh.maritime.edu/stcw/2001/MT-4241.html","source_note":"Timone e governo dell’unità"},{"prompt":"Qual è il compito dell’alternatore di bordo?","options":["Regolare il radar","Aumentare la pressione dell’acqua di mare","Azionare direttamente il timone","Fornire energia elettrica e ricaricare le batterie quando il motore è in funzione"],"correct_index":3,"explanation":"Impianto elettrico e ricarica batterie. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.volvopenta.com/-/media/volvopenta/local/uk/apprenticeship/level-2-foundation-level-marine-engineering.pdf","source_note":"Impianto elettrico e ricarica batterie"},{"prompt":"Qual è il compito della girante della pompa acqua in un fuoribordo o circuito previsto?","options":["Misurare la velocità","Lubrificare il piede poppiero","Azionare il timone","Movimentare l’acqua di raffreddamento nel circuito"],"correct_index":3,"explanation":"Girante e pompa dell’acqua di raffreddamento. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.yamaha-motor.eu/content/dam/yamaha-motor-europe/marine/dealers/2022-workshop-dealer-guide.pdf","source_note":"Girante e pompa dell’acqua di raffreddamento"},{"prompt":"Qual è il compito della pompa di sentina?","options":["Raffreddare l’elica","Regolare l’assetto longitudinale","Aumentare il livello dell’acqua a bordo","Rimuovere l’acqua accumulata nella sentina"],"correct_index":3,"explanation":"Pompa di sentina e controllo dell’acqua a bordo. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.boatus.org/study-guide/the-boat/","source_note":"Pompa di sentina e controllo dell’acqua a bordo"},{"prompt":"Qual è la funzione dei fanali di navigazione?","options":["Sostituire i segnali sonori","Mostrare posizione, aspetto e direzione relativa dell’unità secondo le regole applicabili","Illuminare l’interno della sala macchine","Indicare il livello carburante"],"correct_index":1,"explanation":"Fanali di navigazione e riconoscimento delle unità. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"Fanali di navigazione e riconoscimento delle unità"},{"prompt":"Qual è la funzione del motorino di avviamento?","options":["Azionare la pompa di sentina","Alimentare il GPS","Mettere in rotazione il motore per avviarne il funzionamento autonomo","Regolare l’angolo del timone"],"correct_index":2,"explanation":"Motorino di avviamento. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.volvopenta.com/-/media/volvopenta/local/uk/apprenticeship/level-2-foundation-level-marine-engineering.pdf","source_note":"Motorino di avviamento"},{"prompt":"Qual è la funzione del sistema trim/tilt su un fuoribordo che ne è dotato?","options":["Regolare la tensione della radio","Comandare le pompe di sentina","Aumentare il volume del serbatoio","Modificare l’inclinazione del gruppo propulsore rispetto allo specchio di poppa"],"correct_index":3,"explanation":"Trim e tilt del motore fuoribordo. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.yamaha-motor.eu/content/dam/yamaha-motor-europe/marine/dealers/2022-workshop-dealer-guide.pdf","source_note":"Trim e tilt del motore fuoribordo"},{"prompt":"Qual è la funzione dell’AIS?","options":["Scambiare dati identificativi e dinamici delle unità equipaggiate e ricevere informazioni sul traffico","Azionare la pompa carburante","Comandare automaticamente il timone","Misurare la temperatura dell’acqua"],"correct_index":0,"explanation":"Sistema di identificazione automatica. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.navcen.uscg.gov/","source_note":"Sistema di identificazione automatica"},{"prompt":"Qual è la funzione dell’elica?","options":["Ridurre il dislocamento","Sostituire il timone","Misurare il fondale","Generare la spinta accelerando una massa d’acqua"],"correct_index":3,"explanation":"Propulsione e spinta dell’elica. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://ittc.info/media/10129/2021-ittc-dictionary.pdf","source_note":"Propulsione e spinta dell’elica"},{"prompt":"Qual è la funzione della ventilazione del vano motore nelle unità che la richiedono?","options":["Aumentare la pressione dell’olio","Aumentare il pescaggio","Ridurre l’accumulo di vapori infiammabili e favorire il ricambio d’aria","Raffreddare il GPS"],"correct_index":2,"explanation":"Ventilazione dei compartimenti e prevenzione incendi. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://uscgboating.org/assets/1/AssetManager/ABYC.1002.01.pdf","source_note":"Ventilazione dei compartimenti e prevenzione incendi"},{"prompt":"Qual è la funzione della zattera di salvataggio?","options":["Fornire un mezzo di sopravvivenza collettivo in caso di abbandono dell’unità","Sostituire l’ancora","Raffreddare il motore","Misurare la profondità"],"correct_index":0,"explanation":"Zattera di salvataggio e abbandono nave. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.uscgboating.org/","source_note":"Zattera di salvataggio e abbandono nave"},{"prompt":"Qual è la funzione di un estintore portatile a bordo?","options":["Sostituire il sistema antincendio fisso","Segnalare la posizione GPS","Consentire il primo intervento su un principio d’incendio compatibile con la classe e il tipo di estintore","Raffreddare il motore in esercizio"],"correct_index":2,"explanation":"Dotazioni antincendio e primo intervento. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://uscgboating.org/","source_note":"Dotazioni antincendio e primo intervento"},{"prompt":"Qual è la funzione di una radio VHF marina?","options":["Consentire comunicazioni radio nave-nave e nave-terra sulle frequenze marittime","Regolare il trim","Misurare la profondità","Misurare il livello carburante"],"correct_index":0,"explanation":"Comunicazioni VHF marittime. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.navcen.uscg.gov/","source_note":"Comunicazioni VHF marittime"},{"prompt":"Qual è la funzione principale del GPS nautico?","options":["Rilevare la temperatura dei cilindri","Fornire posizione e dati di navigazione basati sui segnali satellitari","Misurare la pressione dell’olio","Calcolare la velocità dell’elica"],"correct_index":1,"explanation":"Posizionamento satellitare e navigazione. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.navcen.uscg.gov/","source_note":"Posizionamento satellitare e navigazione"},{"prompt":"Qual è la funzione principale dell’olio di lubrificazione di un motore marino?","options":["Aumentare la salinità dell’acqua","Regolare il pescaggio","Ridurre attrito e usura delle parti in movimento e contribuire alla protezione termica","Raffreddare direttamente il radar"],"correct_index":2,"explanation":"Lubrificazione e manutenzione del motore marino. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.volvopenta.com/-/media/volvopenta/local/uk/apprenticeship/level-2-foundation-level-marine-engineering.pdf","source_note":"Lubrificazione e manutenzione del motore marino"},{"prompt":"Qual è lo scopo del controllo di perdite di carburante, olio e refrigerante prima della partenza?","options":["Prevenire incendi, inquinamento, avarie e perdita di affidabilità","Ridurre la visibilità dei fanali","Migliorare la ricezione radio","Aumentare il pescaggio"],"correct_index":0,"explanation":"Controlli pre-partenza di impianti e fluidi. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.boatus.org/preserving-clean-water/boat-maintenance/","source_note":"Controlli pre-partenza di impianti e fluidi"},{"prompt":"Quale anomalia può indicare un allarme acustico di bassa pressione olio o alta temperatura motore?","options":["Che il GPS ha perso i satelliti","Una condizione che richiede riduzione/arresto secondo il manuale e verifica immediata","Che il serbatoio acqua dolce è pieno","Che il radar è in standby"],"correct_index":1,"explanation":"Allarmi motore e diagnosi delle anomalie. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.volvopenta.com/-/media/volvopenta/local/uk/apprenticeship/level-2-foundation-level-marine-engineering.pdf","source_note":"Allarmi motore e diagnosi delle anomalie"},{"prompt":"Quale funzione svolge il filtro carburante con separatore d’acqua?","options":["Aumentare la pressione dell’olio","Misurare il livello della sentina","Trattenere contaminanti e separare l’acqua presente nel carburante","Raffreddare i gas di scarico"],"correct_index":2,"explanation":"Filtrazione carburante e separazione dell’acqua. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.boatus.org/preserving-clean-water/boat-maintenance/","source_note":"Filtrazione carburante e separazione dell’acqua"},{"prompt":"Quale problema può provocare un’elica danneggiata o deformata?","options":["Aumento della capacità del serbatoio","Vibrazioni, perdita di rendimento e possibili sollecitazioni sulla trasmissione","Riduzione della salinità","Migliore equilibrio dinamico"],"correct_index":1,"explanation":"Ispezione e integrità dell’elica. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.boatus.org/study-guide/the-boat/","source_note":"Ispezione e integrità dell’elica"},{"prompt":"Quale rischio comporta la corrosione dello scafo o degli elementi metallici?","options":["Riduzione della massa dell’acqua","Migliore rendimento dell’elica","Aumento della spinta idrostatica","Perdita di integrità strutturale e possibile compromissione della tenuta"],"correct_index":3,"explanation":"Corrosione e integrità dello scafo. Quesito di tecnica generale; dotazioni e procedure effettive vanno sempre verificate sul manuale e sull’allestimento dell’unità.","source_url":"https://www.boatus.org/study-guide/the-boat/","source_note":"Corrosione e integrità dello scafo"}]$sea$::jsonb)
 as q(prompt text, options jsonb, correct_index smallint, explanation text, source_url text, source_note text)
),
targets(vehicle_id,domain) as (values
 ('cc-subaru-crosstrek','land'),('cc-iveco-50c17-op','land'),
 ('cc-defender-110','land'),('cc-jeep-wrangler','land'),
 ('gdf-classe-monti','sea'),('gdf-classe-di-bartolo','sea'),
 ('gdf-classe-bigliani-viii','sea'),('gdf-bso-139','sea')
)
insert into public.vehicle_brevetto_question_bank
(vehicle_id,prompt,options,correct_index,explanation,source_url,source_note,category,active)
select t.vehicle_id,q.prompt,q.options,q.correct_index,q.explanation,q.source_url,q.source_note,'technical',true
from targets t
cross join lateral (
 select * from land_questions where t.domain='land'
 union all
 select * from sea_questions where t.domain='sea'
) q
where not exists (
 select 1 from public.vehicle_brevetto_question_bank existing
 where existing.vehicle_id=t.vehicle_id and existing.category='technical'
 and lower(trim(existing.prompt))=lower(trim(q.prompt))
);
